let windowSmall=window.matchMedia("(max-width: 950px)").matches;function cardMatcher(e){var e=e.id;let c;return e.includes("card")&&(e=e.slice(-1),c={cardId:"card"+e,expandedCardId:"expanded-card"+e,closeCardId:"close-card"+e}),c}function cardToggler(e){document.querySelector("#"+e.cardId).classList.toggle("active-card"),document.querySelector("#"+e.expandedCardId).classList.toggle("active-expanded-card")}function cardCloser(){null!==document.querySelector(".active-card")&&document.querySelector(".active-card").classList.remove("active-card"),null!==document.querySelector(".active-expanded-card")&&document.querySelector(".active-expanded-card").classList.remove("active-expanded-card")}window.addEventListener("DOMContentLoaded",()=>{var e=document.querySelectorAll(".card"),c=document.querySelectorAll(".expanded-card");document.querySelectorAll(".close");e.forEach(d=>{d.addEventListener("click",e=>{var c=cardMatcher(d);d.classList.contains("active-card")||cardCloser(),cardToggler(c)})}),windowSmall&&c.forEach(e=>{var c=cardMatcher(e);document.querySelector("#"+c.cardId).after(e)})});